    vx: (1.5 + Math.random() * 2.2) * (i % 2 === 0 ? 1 : -1),
    vy: (Math.random() - 0.5) * 1.2,
    bit: i % 2 === 0 ? '1' : '0',
    label: ['DỮ LIỆU', 'THÔNG TIN', 'CPU', 'AI', 'BIT 0/1', 'MẠNG', 'THUẬT TOÁN'][i % 7],
    color: ['#34d399', '#fbbf24', '#38bdf8', '#f472b6', '#a78bfa'][i % 5],
    radius: 10 + (i % 4) * 3
